try:
    broadcast_shape((4, 3), (4,))
except ValueError:
    pass
else:
    raise AssertionError('3 and 4 are neither equal nor 1, so this must raise ValueError')

problems.solution:
def broadcast_shape(s1, s2):
    n = max(len(s1), len(s2))
    a = (1,) * (n - len(s1)) + tuple(s1)
    b = (1,) * (n - len(s2)) + tuple(s2)
    out = []
    for x, y in zip(a, b):
        if x != y and x != 1 and y != 1:
            raise ValueError(f'{s1} and {s2} do not broadcast')
        out.append(max(x, y))
    return tuple(out)
